'use client'

import { useState } from 'react'
import Link from 'next/link'
import { useRouter } from 'next/navigation'
import { BandMember } from './actions'
import EditBandMemberModal from './components/EditBandMemberModal'
import { AppOption } from '@/app/lib/options' // Import Type

export default function BandDashboardClient({ 
  initialMembers, 
  instrumentOptions, // <--- Updated Type
  roleOptions 
}: { 
  initialMembers: BandMember[], 
  instrumentOptions: AppOption[], // <--- Updated Type
  roleOptions: string[] 
}) {
  // ... (Rest of component logic is exactly the same) ...
  // ... (Pass props to EditBandMemberModal) ...
  
  // Example of EditModal usage update:
  /*
    {editingMember && (
        <EditBandMemberModal 
            member={editingMember} 
            instrumentOptions={instrumentOptions}
            roleOptions={roleOptions}
            onClose={() => setEditingMember(null)}
            onSuccess={() => {
                setEditingMember(null)
                router.refresh()
            }}
        />
    )}
  */
 
 // (Include the full file content if you need it, but it's largely unchanged except for types)
 const router = useRouter()
 const [searchTerm, setSearchTerm] = useState('')
 const [editingMember, setEditingMember] = useState<BandMember | null>(null)

 const filteredMembers = initialMembers.filter(m => 
   m.last_name.toLowerCase().includes(searchTerm.toLowerCase()) ||
   m.first_name.toLowerCase().includes(searchTerm.toLowerCase()) ||
   (m.band_details?.instrument || '').toLowerCase().includes(searchTerm.toLowerCase())
 )

 return (
   <div className="space-y-6">
     {/* TOOLBAR */}
     <div className="flex flex-col sm:flex-row gap-4 justify-between items-center bg-card p-4 rounded-lg border border-border shadow-sm">
       <input 
         type="text" 
         placeholder="Search by name or instrument..." 
         value={searchTerm}
         onChange={(e) => setSearchTerm(e.target.value)}
         className="w-full sm:w-72 p-2 rounded-md border border-input bg-background text-foreground text-sm focus:ring-2 focus:ring-primary"
       />
       <button 
         onClick={() => window.print()} 
         className="flex items-center gap-2 px-4 py-2 bg-primary text-primary-foreground text-sm font-bold rounded-md hover:bg-primary/90 transition-colors"
       >
         <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M17 17h2a2 2 0 002-2v-4a2 2 0 00-2-2H5a2 2 0 00-2 2v4a2 2 0 002 2h2m2 4h6a2 2 0 002-2v-4a2 2 0 00-2-2H9a2 2 0 00-2 2v4a2 2 0 002 2zm8-12V5a2 2 0 00-2-2H9a2 2 0 00-2 2v4h10z" /></svg>
         Print Roster
       </button>
     </div>

     {/* ROSTER TABLE */}
     <div className="bg-card border border-border rounded-lg overflow-hidden shadow-sm">
       <div className="overflow-x-auto">
         <table className="min-w-full divide-y divide-border">
           <thead className="bg-muted/50">
             <tr>
               <th className="px-6 py-3 text-left text-xs font-bold text-muted-foreground uppercase tracking-wider">Cadet</th>
               <th className="px-6 py-3 text-left text-xs font-bold text-muted-foreground uppercase tracking-wider">Instrument</th>
               <th className="px-6 py-3 text-left text-xs font-bold text-muted-foreground uppercase tracking-wider">Role</th>
               <th className="px-6 py-3 text-left text-xs font-bold text-muted-foreground uppercase tracking-wider">Room</th>
               <th className="px-6 py-3 text-center text-xs font-bold text-muted-foreground uppercase tracking-wider">Tours</th>
               <th className="px-6 py-3 text-right text-xs font-bold text-muted-foreground uppercase tracking-wider">Actions</th>
             </tr>
           </thead>
           <tbody className="bg-card divide-y divide-border">
             {filteredMembers.length > 0 ? (
               filteredMembers.map((member) => (
                 <tr key={member.id} className="hover:bg-accent/50 transition-colors group">
                   <td className="px-6 py-4 whitespace-nowrap">
                     <div>
                       <div className="text-sm font-bold text-foreground">{member.last_name}, {member.first_name}</div>
                       <div className="text-xs text-muted-foreground">{member.cadet_rank} • {member.company?.company_name}</div>
                     </div>
                   </td>
                   <td className="px-6 py-4 whitespace-nowrap text-sm text-foreground">
                     {member.band_details?.instrument || <span className="opacity-50">-</span>}
                   </td>
                   <td className="px-6 py-4 whitespace-nowrap text-sm text-primary font-medium">
                     {member.band_details?.leadership_role || <span className="opacity-50 text-muted-foreground">-</span>}
                   </td>
                   <td className="px-6 py-4 whitespace-nowrap text-sm text-muted-foreground">
                     {member.room_number || '-'}
                   </td>
                   <td className="px-6 py-4 whitespace-nowrap text-center">
                       <span className={`inline-flex items-center px-2 py-0.5 rounded text-xs font-bold ${member.cached_tour_balance > 0 ? 'bg-destructive/10 text-destructive' : 'bg-muted text-muted-foreground'}`}>
                           {member.cached_tour_balance}
                       </span>
                   </td>
                   <td className="px-6 py-4 whitespace-nowrap text-right text-sm font-medium space-x-4">
                     <button 
                       onClick={() => setEditingMember(member)}
                       className="text-primary hover:text-primary/80 transition-colors"
                     >
                       Edit Details
                     </button>
                     <Link href={`/profile/${member.id}`} className="text-muted-foreground hover:text-foreground transition-colors">
                       Profile
                     </Link>
                   </td>
                 </tr>
               ))
             ) : (
               <tr>
                 <td colSpan={6} className="px-6 py-12 text-center text-muted-foreground italic">
                   No band members found.
                 </td>
               </tr>
             )}
           </tbody>
         </table>
       </div>
     </div>

     {/* EDIT MODAL */}
     {editingMember && (
       <EditBandMemberModal 
           member={editingMember} 
           instrumentOptions={instrumentOptions}
           roleOptions={roleOptions}
           onClose={() => setEditingMember(null)}
           onSuccess={() => {
               setEditingMember(null)
               router.refresh()
           }}
       />
     )}
   </div>
 )
}